class Weight
  include Comparable

  attr_reader :amount, :unit

  def initialize(amount, unit)
    @amount = amount
    @unit = unit
  end

  def ==(other)
    return false unless other.is_a?(Weight)
    @unit == other.unit && @amount == other.amount
  end

  def <=>(other)
    return nil unless other.is_a?(Weight)
    unless @unit == other.unit
      raise ArgumentError, "Cannot compare Weights with different units: #{@unit} vs #{other.unit}"
    end
    @amount <=> other.amount
  end

  def clamp(min = 0, max = nil)
    min ||= 0
    max ||= self
    ensure_same_unit(min, "min")
    ensure_same_unit(max, "max")
    super
  end

  private

  def ensure_same_unit(other, label)
    raise ArgumentError, "Cannot use #{label} with different unit: #{@unit} vs #{other.unit}" unless other.is_a?(Weight) && @unit == other.unit
  end
end
