class OpenRecord
  attr_reader :attributes

  def initialize(**attrs)
    @attributes = attrs
    attrs.each_key { |k| define_accessor(k) }
  end

  def respond_to?(name, include_all = false)
    super || attribute?(name)
  end

  private

  def attribute?(name)
    name = name.to_s
    name.end_with?('=') ? (name[0..-2] && @attributes.key?(name[0..-2].to_sym) || true) : @attributes.key?(name.to_sym)
  end

  def define_accessor(name)
    return if name.to_s.end_with?('=')
    singleton_class.class_eval do
      define_method(name) { @attributes[name.to_sym] }
      define_method("#{name}=") { |value| @attributes[name.to_sym] = value }
    end
  end

  public

  def method_missing(name, *args, &block)
    if name.to_s.end_with?('=') && args.length == 1
      key = name.to_s[0..-2].to_sym
      @attributes[key] = args.first
      define_accessor(key)
    else
      key = name.to_sym
      if @attributes.key?(key)
        @attributes[key]
      else
        super
      end
    end
  end
end
